fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    match len {
        0 => (vec![], vec![]),
        1 => (vec![a[0]], vec![]),  // Could also return (vec![], vec![a[0]])
        _ => {
            // Split after the first element to ensure both parts are non-empty
            // and strictly shorter than the original
            let first = a[0..1].to_vec();
            let second = a[1..].to_vec();
            (first, second)
        }
    }
}